<template>
  <div class="tp-page">
    <t-card class="tp-card">
      <template #title>
        <div class="tp-head">
          <span class="tp-title">问题标签</span>
          <span class="tp-sub">
            共 {{ tags.length }} 个概念。每个概念下面列出它的全部同义词——
            搜索任一种说法都能找到同一批题，而展示与筛选用的一律是概念名。
          </span>
        </div>
      </template>

      <div v-if="loading" class="tp-hint">加载中…</div>
      <div v-else-if="loadFailed" class="tp-hint tp-hint-error">标签加载失败，请刷新重试</div>
      <div v-else-if="tags.length === 0" class="tp-hint">暂无标签</div>
      <div v-else class="tp-grid">
        <div
          v-for="tag in tags"
          :key="tag.id"
          class="tp-item"
          :class="{ 'tp-item-active': activeTagName === tag.name }"
          @click="goTag(tag)"
        >
          <div class="tp-name">{{ tag.name }}</div>
          <div v-if="tag.aliases && tag.aliases.length" class="tp-aliases">
            <span v-for="alias in tag.aliases" :key="alias" class="tp-alias">{{ alias }}</span>
          </div>
          <div v-else class="tp-no-alias">暂无同义词</div>
        </div>
      </div>
    </t-card>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { GetProblemTagList } from "@/apis/problem.ts";

// 本地接口而不是复用 ProblemTag：aliases 是后端按需填充的字段（gorm:"-"），
// 只在这个页面用得到，不值得为它改动共享类型。
interface TagItem {
  id: number;
  name: string;
  aliases?: string[];
}

const tags = ref<TagItem[]>([]);
const loading = ref(false);
const loadFailed = ref(false);
const router = useRouter();
const route = useRoute();

// 从题目列表点标签过来时带上 ?tag=xxx，高亮当前筛的那个概念，便于对照
const activeTagName = computed(() => (route.query.tag as string) || "");

const fetchTags = async () => {
  loading.value = true;
  loadFailed.value = false;
  try {
    // -1 = 全量。这个页面就是要展示全部概念，不做渲染裁剪
    const res = await GetProblemTagList(-1);
    if (res.code === 0) {
      tags.value = (res.data?.list ?? []) as TagItem[];
    } else {
      loadFailed.value = true;
    }
  } catch (err) {
    // 必须吞掉异常：没有 catch 的话请求一旦失败，整个组件的渲染会被打断，
    // 页面看起来就是「标签一个都没显示」而没有任何提示
    console.error(err);
    loadFailed.value = true;
  } finally {
    loading.value = false;
  }
};

// 点标签 = 回题目列表按它筛题。传概念名而不是别名：SearchTagIds 第一步就查别名表，
// 用概念名或任一同义词效果一致，而概念名在 URL 里更可读。
const goTag = (tag: TagItem) => {
  router.push({ name: "problem-list", query: { tag: tag.name } });
};

onMounted(fetchTags);
</script>

